style.css:
body {
  /* Fallback color in case the browser doesn't support gradients */
  background-color: #4682b4; 
  
  /* Linear gradient from blue at the top to white at the bottom */
  background-image: linear-gradient(to bottom, #4682b4, #ffffff);
  
  /* Ensure the background covers the entire height of the viewport */
  min-height: 100vh;
  
  /* Optional: keeps the gradient fixed in position as you scroll down the page */
  background-attachment: fixed; 
  
  /* Optional: removes default body margins */
  margin: 0;
}
